export const UI_CLIPBOARD_WRITER = new InjectionToken<ClipboardWriter>('UI_CLIPBOARD_WRITER', {
  providedIn: 'root',
  factory: () => {
    const document = inject(DOCUMENT);
    return async text => {
      const clipboard = document.defaultView?.navigator.clipboard;
      if (!clipboard) throw new Error('Clipboard API is unavailable.');
      await clipboard.writeText(text);
    };
  },
});

export function injectComponentMessageText<Id extends UiPatternMessageId>(
  catalog: Readonly<Record<Id, UiMessagePattern>>,
): (request: UiMessageRequest<Id>) => string;

export interface GridTreeRow {
    id: string;
    parentId: string | null;
